mapper.select:
SELECT pay.payment_id, pay.payment_amount, pay.created_at, place.place_name,
AS payment_type
FROM ( SELECT p.*, GROUP_CONCAT(DISTINCT pd.payment_type ORDER BY pd.payment_type SEPARATOR ',') AS all_types FROM payments p JOIN payment_detail pd ON p.payment_id = pd.payment_id WHERE p.store_id = #{storeId} GROUP BY p.payment_id ) pay JOIN places place ON pay.place_id = place.place_id JOIN orders O ON pay.order_id = O.order_id GROUP BY pay.payment_id;

mapper.update:
UPDATE payments
SET status = #{status}
WHERE payment_id = #{paymentId}
